const withDevtools = <const Caps extends readonly AnyCapability[], A, E, R>(
  caps: Caps,
  build: (
    projected: Effect.Success<ReturnType<typeof devtools<Caps>>>
  ) => Layer.Layer<A, E, R>
) => Layer.unwrap(Effect.map(devtools(caps), build));

const toolkitServer = <const Caps extends readonly AnyCapability[]>(
  all: Caps
) => {
  const projected = toToolkit(all);

  return McpServer.toolkit(projected.toolkit).pipe(
    Layer.provideMerge(projected.layer)
  );
};

export const devtoolsRoutes = withDevtools(
  capabilities,
  ({ capabilities: all, recorded }) => {
    const api = toHttpApi("RatStack", recorded);

    return Layer.mergeAll(
      HttpApiBuilder.layer(api.api, { openapiPath: "/openapi.json" }).pipe(
        Layer.provide(api.layer)
      ),
      HttpApiScalar.layer(api.api, { path: "/docs" }),
      toolkitServer(all).pipe(
        Layer.provide(
          McpServer.layerHttp({
            name: "rat-stack-devtools",
            path: DEVTOOLS_MCP_PATH,
            protocols: mcpProtocols,
            version: VERSION,
          })
        )
      )
    );
  }
);

export const devtoolsWebServer = (port: number) =>
  HttpRouter.serve(devtoolsRoutes).pipe(
    Layer.provide(devtoolsLayer()),
    Layer.provide(serverLayer(port))
  );

export const mcpServer = {
  codeMode: withStdio(
    McpServer.toolkit(codeMode.toolkit).pipe(
      Layer.provideMerge(codeMode.layer),
      Layer.provide(layerSubprocess())
    )
  ),
  devtools: withStdio(
    withDevtools(cliCapabilities, ({ capabilities: all }) => toolkitServer(all))
  ).pipe(Layer.provide(devtoolsLayer())),
  devtoolsCodeMode: withStdio(
    withDevtools(cliCapabilities, ({ capabilities: all }) => {
      const projected = toCodeMode(all);

      return McpServer.toolkit(projected.toolkit).pipe(
        Layer.provideMerge(projected.layer),
        Layer.provide(layerSubprocess())
      );
    })
  ).pipe(Layer.provide(devtoolsLayer())),
  tools: withStdio(
    McpServer.toolkit(tools.toolkit).pipe(Layer.provideMerge(tools.layer))
  ),
} as const;

import * as Alchemy from "alchemy";
import { adopt } from "alchemy/AdoptPolicy";
import * as Cloudflare from "alchemy/Cloudflare";
import * as Drizzle from "alchemy/Drizzle/Providers";
import { retain } from "alchemy/RemovalPolicy";
import * as Config from "effect/Config";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Redacted from "effect/Redacted";
import * as Schema from "effect/Schema";

import privateAuth from "../site/src/auth/private-worker.js";
import Mischief from "../site/src/worker.js";
import { Website } from "../web/src/website.js";

export default Alchemy.Stack(
  "RatStack",
  {
    providers: Layer.mergeAll(Cloudflare.providers(), Drizzle.providers()),
    state: Cloudflare.state(),
  },
  Effect.gen(function* stack() {
    const dev = yield* Alchemy.ALCHEMY_DEV;

    if (!dev) {
      const zone = yield* Cloudflare.Zone.Zone("RatstackZone", {
        name: "ratstack.sh",
      }).pipe(adopt(true), retain());

      const dnsAidService = (
        id: string,
        name:
          | `_a2a._agents.${string}`
          | `_index._agents.${string}`
          | `_mcp._agents.${string}`
      ) =>
        Cloudflare.DNS.Record(id, {
          content: {
            priority: 1,
            target: "ratstack.sh.",
            value: 'mandatory="alpn,port" alpn="h2" port="443"',
          },
          name,
          ttl: 3600,
          type: "SVCB",
          zoneId: zone.zoneId,
        }).pipe(retain());

      yield* dnsAidService("DnsAidIndexSvcb", "_index._agents.ratstack.sh");
      yield* dnsAidService("DnsAidA2aSvcb", "_a2a._agents.ratstack.sh");
      yield* dnsAidService("DnsAidMcpSvcb", "_mcp._agents.ratstack.sh");
      yield* Cloudflare.DNS.Record("DnsAidIndexTxt", {
        content: '"agents=rat-stack:mcp,rat-stack:a2a"',
        name: "_index._agents.ratstack.sh",
        ttl: 3600,
        type: "TXT",
        zoneId: zone.zoneId,
      }).pipe(retain());

      yield* Cloudflare.DNS.Record("PostShibaDkimCname", {
        content: "174.customers.postshiba.com",
        name: "ps1._domainkey.ratstack.sh",
        proxied: false,
        ttl: 3600,
        type: "CNAME",
        zoneId: zone.zoneId,
      }).pipe(retain());

      yield* Cloudflare.DNS.Record("PostShibaReturnPathCname", {
        content: "rp.postshiba.com",
        name: "rp.ratstack.sh",
        proxied: false,
        ttl: 3600,
        type: "CNAME",
        zoneId: zone.zoneId,
      }).pipe(retain());

      yield* Cloudflare.DNS.Record("DmarcTxt", {
        content: '"v=DMARC1; p=none;"',
        name: "_dmarc.ratstack.sh",
        ttl: 3600,
        type: "TXT",
        zoneId: zone.zoneId,
      }).pipe(retain());

      const forwardTo = yield* Config.schema(
        Schema.Redacted(Schema.NonEmptyString),
        "EMAIL_FORWARD_TO"
      );

      const routing = yield* Cloudflare.Email.Routing("RatstackEmailRouting", {
        zone: zone.zoneId,
      }).pipe(retain());

      const address = yield* Cloudflare.Email.Address(
        "WorkshopForwardAddress",
        {
          email: Redacted.value(forwardTo),
        }
      ).pipe(retain());

      yield* Cloudflare.Email.Rule("WorkshopForwardRule", {
        actions: [{ type: "forward", value: [address.email] }],
        enabled: true,
        matchers: [
          { field: "to", type: "literal", value: "workshop@ratstack.sh" },
        ],
        name: "workshop",
        zone: routing.zoneId,
      }).pipe(retain());

      yield* Cloudflare.DNS.Dnssec("RatstackDnssec", {
        status: "active",
        zoneId: zone.zoneId,
      }).pipe(adopt(true), retain());
    }

    const website = yield* Website;

    const mischief = yield* Mischief;

    yield* mischief.bind`${website}`({
      bindings: [
        { name: "WEBSITE", service: website.workerName, type: "service" },
      ],
    });

    return { mischiefUrl: mischief.url, websiteUrl: website.url };
  }).pipe(
    Effect.provide(
      Layer.unwrap(
        Config.Boolean("AUTH_ENABLED").pipe(
          Config.withDefault(false),
          Effect.map((enabled) => (enabled ? privateAuth : Layer.empty))
        )
      )
    )
  )
);

// @effect-diagnostics anyUnknownInErrorContext:off unsafeEffectTypeAssertion:off missingEffectContext:off -- This projection erases each capability's schema and requirement types while building the heterogeneous RpcGroup and recovers them at its public boundary.
import type { Layer } from "effect";
import { Effect } from "effect";
import type * as Rpc from "effect/rpc/Rpc";
import type * as RpcGroup from "effect/rpc/RpcGroup";

import type { AnyCapability, ContractOf, RequirementsOf } from "./contract.js";
import { toRpcGroup } from "./to-rpc-group.js";
import type { RpcsOf } from "./to-rpc-group.js";

export type ContractsOf<Caps extends readonly AnyCapability[]> = {
  readonly [K in keyof Caps]: ContractOf<Caps[K]>;
};

export interface RpcProjection<Caps extends readonly AnyCapability[]> {
  readonly group: RpcGroup.RpcGroup<RpcsOf<ContractsOf<Caps>>[number]>;
  readonly layer: Layer.Layer<
    Rpc.ToHandler<RpcsOf<ContractsOf<Caps>>[number]>,
    never,
    RequirementsOf<Caps>
  >;
}

export const toRpc = <const Caps extends readonly AnyCapability[]>(
  capabilities: Caps
): RpcProjection<Caps> => {
  const contracts = capabilities.map((capability) => capability.contract);
  // SAFETY: mapping preserves the capability order and each implementation exposes its exact contract.
  // oxlint-disable-next-line typescript/no-unsafe-type-assertion
  const contractTuple = contracts as ContractsOf<Caps>;
  const { group } = toRpcGroup(contractTuple);

  const built = group.toLayer(
    Effect.gen(function* buildHandlers() {
      const context = yield* Effect.context<RequirementsOf<Caps>>();

      const handlers: Record<
        string,
        (
          // oxlint-disable-next-line anti-slop/no-unknown-parameters -- RpcGroup invokes this only after decoding the RPC payload schema.
          payload: unknown
        ) => Effect.Effect<unknown, unknown>
      > = {};

      for (const capability of capabilities) {
        // SAFETY: the server decodes this RPC's payload schema before dispatch, and the capability's requirements are included in RequirementsOf<Caps>.
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion
        const run = capability.handler as (
          // oxlint-disable-next-line anti-slop/no-unknown-parameters -- RpcGroup invokes this only after decoding the RPC payload schema.
          input: unknown
        ) => Effect.Effect<unknown, unknown, RequirementsOf<Caps>>;

        handlers[capability.contract.name] = (payload) =>
          run(payload).pipe(Effect.provideContext(context));
      }

      // SAFETY: the loop uses each capability contract's exact name, and its handler dispatches through that contract's schema-backed RPC definition.
      // oxlint-disable-next-line typescript/no-unsafe-type-assertion, anti-slop/no-chained-type-assertions -- This heterogeneous projection recovers the mapped handlers after the runtime name-indexed loop.
      return handlers as unknown as RpcGroup.HandlersFrom<
        RpcsOf<ContractsOf<Caps>>[number]
      >;
    })
  );

  // SAFETY: the group contains exactly the RPCs derived from the capability contracts, and the handlers capture but do not provide their requirements.
  // oxlint-disable-next-line typescript/no-unsafe-type-assertion
  const layer = built as RpcProjection<Caps>["layer"];

  return { group, layer };
};

