import { Record, Schema } from "effect";
import { Dom, Subscription } from "foldkit";
import { defineMessageUnion } from "foldkit/message";

import { isEasingSpec } from "./easing.pure.js";
import * as SpringMotion from "./spring.pure.js";
import type { Spring, SpringConfig } from "./spring.pure.js";
import * as TweenMotion from "./tween.pure.js";
import type { Tween, TweenOptions } from "./tween.pure.js";

export const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";

const conforms =
  <Value>() =>
  <Codec extends Schema.Schema<Value>>(codec: Codec) =>
    codec;

export const EasingSpecSchema = Schema.String.pipe(
  Schema.refine(isEasingSpec, {
    description:
      "An easing name, cubic-bezier(x1, y1, x2, y2), or steps(count, position)",
  })
);

export const TweenSchema = conforms<Tween>()(
  Schema.Struct({
    duration: Schema.Finite,
    easing: EasingSpecSchema,
    from: Schema.Finite,
    kind: Schema.Literal("tween"),
    startedAt: Schema.Finite,
    to: Schema.Finite,
  })
);

export const SpringConfigSchema = conforms<SpringConfig>()(
  Schema.Struct({
    damping: Schema.Finite,
    mass: Schema.Finite,
    restDelta: Schema.Finite,
    restSpeed: Schema.Finite,
    stiffness: Schema.Finite,
  })
);

export const SpringSchema = conforms<Spring>()(
  Schema.Struct({
    config: SpringConfigSchema,
    kind: Schema.Literal("spring"),
    position: Schema.Array(Schema.Finite),
    remainder: Schema.Finite,
    settled: Schema.Boolean,
    target: Schema.Array(Schema.Finite),
    velocity: Schema.Array(Schema.Finite),
  })
);

export const Clock = Schema.Struct({
  now: Schema.Finite,
  reducedMotion: Schema.Boolean,
});

export type MotionClock = typeof Clock.Type;

export const initialClock: MotionClock = { now: 0, reducedMotion: false };

export const Message = defineMessageUnion({
  ChangedReducedMotion: { isReducedMotion: Schema.Boolean },
  TickedFrame: { elapsed: Schema.Finite },
});

export type MotionMessage = typeof Message.Type;

export interface Motion<
  TweenKey extends string = string,
  SpringKey extends string = string,
> {
  readonly clock: MotionClock;
  readonly tweens: Readonly<Record<TweenKey, Tween>>;
  readonly springs: Readonly<Record<SpringKey, Spring>>;
}

export interface MotionKeys<TweenKey extends string, SpringKey extends string> {
  readonly tweens: readonly TweenKey[];
  readonly springs: readonly SpringKey[];
}

export const motionSchema = <
  const TweenKey extends string,
  const SpringKey extends string,
>(
  keys: MotionKeys<TweenKey, SpringKey>
) =>
  Schema.Struct({
    clock: Clock,
    springs: Schema.Record(Schema.Literals(keys.springs), SpringSchema),
    tweens: Schema.Record(Schema.Literals(keys.tweens), TweenSchema),
  });

export const isAnimating = <TweenKey extends string, SpringKey extends string>(
  motion: Motion<TweenKey, SpringKey>
) =>
  Object.values<Tween>(motion.tweens).some(
    (animation) => !TweenMotion.isDone(animation, motion.clock.now)
  ) ||
  Object.values<Spring>(motion.springs).some(
    (animation) => !SpringMotion.isSettled(animation)
  );

const settleAll = <TweenKey extends string, SpringKey extends string>(
  motion: Motion<TweenKey, SpringKey>
): Motion<TweenKey, SpringKey> => ({
  clock: motion.clock,
  // oxlint-disable-next-line unicorn/no-array-method-this-argument -- Record.map is the Effect record combinator, not Array#map with a thisArg.
  springs: Record.map(motion.springs, SpringMotion.snap),
  // oxlint-disable-next-line unicorn/no-array-method-this-argument -- Record.map is the Effect record combinator, not Array#map with a thisArg.
  tweens: Record.map(motion.tweens, (animation) =>
    TweenMotion.finish(animation, motion.clock.now)
  ),
});

export const advance = <TweenKey extends string, SpringKey extends string>(
  motion: Motion<TweenKey, SpringKey>,
  message: MotionMessage
): Motion<TweenKey, SpringKey> =>
  Message.match<Motion<TweenKey, SpringKey>>(message, {
    ChangedReducedMotion: ({ isReducedMotion }) => {
      const next = {
        ...motion,
        clock: { ...motion.clock, reducedMotion: isReducedMotion },
      };

      return isReducedMotion ? settleAll(next) : next;
    },
    TickedFrame: ({ elapsed }) => {
      const span = Math.min(SpringMotion.MAX_STEP_MS, Math.max(0, elapsed));

      const next = {
        clock: { ...motion.clock, now: motion.clock.now + span },
        // oxlint-disable-next-line unicorn/no-array-method-this-argument -- Record.map is the Effect record combinator, not Array#map with a thisArg.
        springs: Record.map(motion.springs, (animation) =>
          SpringMotion.step(animation, span)
        ),
        tweens: motion.tweens,
      };

      return next.clock.reducedMotion ? settleAll(next) : next;
    },
  });

export const startTween = (
  clock: MotionClock,
  options: Omit<TweenOptions, "startedAt">
): Tween =>
  TweenMotion.tween({
    ...options,
    duration: clock.reducedMotion ? 0 : options.duration,
    startedAt: clock.now,
  });

export const retargetTween = (
  clock: MotionClock,
  animation: Tween,
  to: number
): Tween => {
  const next = TweenMotion.retarget(animation, to, clock.now);

  return clock.reducedMotion ? TweenMotion.finish(next, clock.now) : next;
};

export const retargetSpring = (
  clock: MotionClock,
  animation: Spring,
  target: readonly number[]
): Spring => {
  const next = SpringMotion.retarget(animation, target);

  return clock.reducedMotion ? SpringMotion.snap(next) : next;
};

export interface MotionSubscriptionOptions<Model, Message> {
  readonly isAnimating: (model: Model) => boolean;
  readonly toMessage: (message: MotionMessage) => Message;
}

export const motionSubscriptions = <Model, Message>(
  options: MotionSubscriptionOptions<Model, Message>
) =>
  Subscription.make<Model, Message>()(() => ({
    motionFrame: Subscription.animationFrameEntry<Model, Message>({
      isActive: options.isAnimating,
      toMessage: (elapsed) =>
        options.toMessage(Message.TickedFrame({ elapsed })),
    }),
    reducedMotion: Subscription.persistentEntry(
      Dom.streamFromMediaQuery({
        mapMatches: (isReducedMotion) =>
          options.toMessage(Message.ChangedReducedMotion({ isReducedMotion })),
        query: REDUCED_MOTION_QUERY,
      })
    ),
  }));

import { MotionInputError } from "./easing.pure.js";
import type { Vector } from "./interpolate.pure.js";

export interface SpringConfig {
  readonly stiffness: number;
  readonly damping: number;
  readonly mass: number;
  readonly restDelta: number;
  readonly restSpeed: number;
}

export interface Spring {
  readonly kind: "spring";
  readonly config: SpringConfig;
  readonly position: Vector;
  readonly velocity: Vector;
  readonly target: Vector;
  readonly remainder: number;
  readonly settled: boolean;
}

export type MutableVector = number[] | Float64Array;

export interface MutableSpring<Storage extends MutableVector = MutableVector> {
  readonly kind: "spring";
  config: SpringConfig;
  position: Storage;
  velocity: Storage;
  target: Storage;
  remainder: number;
  settled: boolean;
}

export const SUBSTEP_MS = 1000 / 120;

export const MAX_STEP_MS = 100;

const SUBSTEP_SECONDS = SUBSTEP_MS / 1000;

const SUBSTEP_GRID_TOLERANCE = 1e-9;

const DEFAULT_REST_DELTA = 0.001;

const DEFAULT_REST_SPEED = 0.001;

export interface SpringParameters {
  readonly stiffness: number;
  readonly damping: number;
  readonly mass?: number;
  readonly restDelta?: number;
  readonly restSpeed?: number;
}

const requirePositive = (name: string, value: number, fix: string) => {
  if (!(value > 0 && Number.isFinite(value))) {
    throw new MotionInputError(`Spring ${name} is ${value}. ${fix}`);
  }
};

export const springConfig = (parameters: SpringParameters): SpringConfig => {
  const config = {
    damping: parameters.damping,
    mass: parameters.mass ?? 1,
    restDelta: parameters.restDelta ?? DEFAULT_REST_DELTA,
    restSpeed: parameters.restSpeed ?? DEFAULT_REST_SPEED,
    stiffness: parameters.stiffness,
  };

  requirePositive(
    "stiffness",
    config.stiffness,
    "Pass a finite stiffness above 0, or use critical(frequency)."
  );
  requirePositive(
    "mass",
    config.mass,
    "Pass a finite mass above 0; 1 is the usual choice."
  );
  requirePositive(
    "restDelta",
    config.restDelta,
    "Pass a finite settle distance above 0 in the same units as the position."
  );
  requirePositive(
    "restSpeed",
    config.restSpeed,
    "Pass a finite settle speed above 0 in position units per second."
  );

  if (!(config.damping >= 0 && Number.isFinite(config.damping))) {
    throw new MotionInputError(
      `Spring damping is ${config.damping}. Pass a finite damping of 0 or more; 0 never settles.`
    );
  }

  return config;
};

export const critical = (
  frequency: number,
  options: Omit<SpringParameters, "stiffness" | "damping"> = {}
): SpringConfig => {
  requirePositive(
    "frequency",
    frequency,
    "Pass the undamped frequency in hertz, above 0."
  );

  const mass = options.mass ?? 1;
  const angular = 2 * Math.PI * frequency;

  return springConfig({
    ...options,
    damping: 2 * mass * angular,
    mass,
    stiffness: mass * angular * angular,
  });
};

const atRest = (
  config: SpringConfig,
  position: ArrayLike<number>,
  velocity: ArrayLike<number>,
  target: ArrayLike<number>
) => {
  for (let index = 0; index < position.length; index += 1) {
    if (
      Math.abs((position[index] ?? 0) - (target[index] ?? 0)) >
        config.restDelta ||
      Math.abs(velocity[index] ?? 0) > config.restSpeed
    ) {
      return false;
    }
  }

  return true;
};

const requireDimensions = (position: Vector, other: Vector, name: string) => {
  if (position.length !== other.length) {
    throw new MotionInputError(
      `Spring position has ${position.length} components but its ${name} has ${other.length}. Give the position, velocity and target the same number of components.`
    );
  }
};

const snapInto = <Into extends MutableSpring>(into: Into): Into => {
  for (let index = 0; index < into.position.length; index += 1) {
    into.position[index] = into.target[index] ?? 0;
    into.velocity[index] = 0;
  }

  into.remainder = 0;
  into.settled = true;

  return into;
};

const settleIfAtRest = (candidate: MutableSpring<number[]>): Spring =>
  atRest(
    candidate.config,
    candidate.position,
    candidate.velocity,
    candidate.target
  )
    ? snapInto(candidate)
    : candidate;

export interface SpringOptions {
  readonly config: SpringConfig;
  readonly position: Vector;
  readonly target?: Vector;
  readonly velocity?: Vector;
}

export const spring = (options: SpringOptions): Spring => {
  const target = [...(options.target ?? options.position)];

  const velocity = [
    ...(options.velocity ?? Array.from(options.position, () => 0)),
  ];

  requireDimensions(options.position, target, "target");
  requireDimensions(options.position, velocity, "velocity");

  return settleIfAtRest({
    config: options.config,
    kind: "spring",
    position: [...options.position],
    remainder: 0,
    settled: false,
    target,
    velocity,
  });
};

const substepInto = (into: MutableSpring) => {
  const { damping, mass, stiffness } = into.config;

  for (let index = 0; index < into.position.length; index += 1) {
    const position = into.position[index] ?? 0;
    const velocity = into.velocity[index] ?? 0;

    const acceleration =
      (-stiffness * (position - (into.target[index] ?? 0)) -
        damping * velocity) /
      mass;

    const nextVelocity = velocity + acceleration * SUBSTEP_SECONDS;

    into.velocity[index] = nextVelocity;
    into.position[index] = position + nextVelocity * SUBSTEP_SECONDS;
  }
};

const copyInto = (from: Spring | MutableSpring, into: MutableSpring) => {
  if (from === into) {
    return;
  }

  into.config = from.config;
  into.remainder = from.remainder;
  into.settled = from.settled;

  for (let index = 0; index < from.position.length; index += 1) {
    into.position[index] = from.position[index] ?? 0;
    into.velocity[index] = from.velocity[index] ?? 0;
    into.target[index] = from.target[index] ?? 0;
  }
};

export const stepInto = <Into extends MutableSpring>(
  from: Spring | MutableSpring,
  elapsed: number,
  into: Into
): Into => {
  copyInto(from, into);

  if (into.settled) {
    into.remainder = 0;

    return into;
  }

  const span = Math.min(MAX_STEP_MS, Math.max(0, elapsed));
  const ticks = into.remainder + span / SUBSTEP_MS;
  const substeps = Math.floor(ticks + SUBSTEP_GRID_TOLERANCE);

  for (let substep = 0; substep < substeps; substep += 1) {
    substepInto(into);

    if (atRest(into.config, into.position, into.velocity, into.target)) {
      return snapInto(into);
    }
  }

  into.remainder = Math.max(0, ticks - substeps);

  return into;
};

const copyOf = (from: Spring): MutableSpring<number[]> => ({
  config: from.config,
  kind: "spring",
  position: [...from.position],
  remainder: from.remainder,
  settled: from.settled,
  target: [...from.target],
  velocity: [...from.velocity],
});

export const step = (from: Spring, elapsed: number): Spring =>
  stepInto(from, elapsed, copyOf(from));

export const snap = (from: Spring): Spring => snapInto(copyOf(from));

export const retarget = (from: Spring, target: Vector): Spring => {
  requireDimensions(from.position, target, "target");

  return settleIfAtRest({
    ...copyOf(from),
    settled: false,
    target: [...target],
  });
};

export const isSettled = (from: Spring) => from.settled;

import { describe, expect, it } from "@effect/vitest";
import { Schema } from "effect";
import * as Arbitrary from "effect/Arbitrary";

import { Spring } from "../src/index.js";
import {
  between,
  coordinate,
  falsifies,
  integerBetween,
  vectorOf,
} from "./arbitraries.js";

const FRAME_MS = 1000 / 60;

const settleWithin = (
  advance: (from: Spring.Spring, elapsed: number) => Spring.Spring,
  start: Spring.Spring,
  limitMs: number
) => {
  let current = start;

  for (let elapsed = 0; elapsed <= limitMs; elapsed += FRAME_MS) {
    if (Spring.isSettled(current)) {
      return current;
    }

    current = advance(current, FRAME_MS);
  }

  return Spring.isSettled(current) ? current : undefined;
};

const settlesAndSnaps = (
  advance: (from: Spring.Spring, elapsed: number) => Spring.Spring,
  start: Spring.Spring,
  limitMs: number
) => {
  const settled = settleWithin(advance, start, limitMs);

  return (
    settled !== undefined &&
    settled.position.every((value, index) => value === start.target[index]) &&
    settled.velocity.every((value) => value === 0)
  );
};

const neverCrossesTarget = (start: Spring.Spring) => {
  const [origin = 0] = start.position;
  const [target = 0] = start.target;
  const side = Math.sign(origin - target);
  let current = start;

  for (let frame = 0; frame < 2000 && !Spring.isSettled(current); frame += 1) {
    current = Spring.step(current, FRAME_MS);

    if (Math.sign((current.position[0] ?? 0) - target) === -side) {
      return false;
    }
  }

  return true;
};

const criticalStart = Arbitrary.all({
  frequency: between(0.5, 8),
  origin: coordinate,
  target: coordinate,
}).pipe(
  Arbitrary.map(({ frequency, origin, target }) => ({
    frequency,
    spring: Spring.spring({
      config: Spring.critical(frequency),
      position: [origin],
      target: [target],
    }),
  }))
);

const movingSpring = Arbitrary.all({
  frequency: between(0.5, 8),
  position: vectorOf(3),
  ratio: between(0.2, 1.5),
  target: vectorOf(3),
  velocity: vectorOf(3),
}).pipe(
  Arbitrary.map(({ frequency, position, ratio, target, velocity }) => {
    const critical = Spring.critical(frequency);

    return Spring.spring({
      config: Spring.springConfig({
        damping: critical.damping * ratio,
        stiffness: critical.stiffness,
      }),
      position,
      target,
      velocity,
    });
  })
);

const settlingSpring = Arbitrary.all({
  frequency: between(0.3, 8),
  offset: between(-0.005, 0.005),
  ratio: between(0.01, 1),
  target: coordinate,
  velocity: between(-0.025, 0.025),
}).pipe(
  Arbitrary.map(({ frequency, offset, ratio, target, velocity }) => {
    const critical = Spring.critical(frequency);

    return {
      ...Spring.spring({
        config: Spring.springConfig({
          damping: critical.damping * ratio,
          stiffness: critical.stiffness,
        }),
        position: [target + 1],
        target: [target],
      }),
      position: [target + offset],
      velocity: [velocity],
    };
  })
);

const anySpring = Arbitrary.flatMap(
  Arbitrary.schema(Schema.Boolean),
  (settling) => (settling ? settlingSpring : movingSpring)
);

const keepsMotionAcrossRetarget = (
  retarget: (from: Spring.Spring, target: readonly number[]) => Spring.Spring,
  from: Spring.Spring,
  target: readonly number[]
) => {
  const next = retarget(from, target);

  return (
    Spring.isSettled(next) ||
    (next.position.every((value, index) => value === from.position[index]) &&
      next.velocity.every((value, index) => value === from.velocity[index]))
  );
};

const springsEqual = (left: Spring.Spring, right: Spring.Spring) =>
  left.settled === right.settled &&
  left.position.every((value, index) => value === right.position[index]) &&
  left.velocity.every((value, index) => value === right.velocity[index]);

const splitAgrees = (
  advance: (from: Spring.Spring, elapsed: number) => Spring.Spring,
  from: Spring.Spring,
  first: number,
  second: number
) =>
  springsEqual(
    advance(
      advance(from, first * Spring.SUBSTEP_MS),
      second * Spring.SUBSTEP_MS
    ),
    advance(from, (first + second) * Spring.SUBSTEP_MS)
  );

const wholeFrameEuler = (
  from: Spring.Spring,
  elapsed: number
): Spring.Spring => {
  const seconds = elapsed / 1000;

  const velocity = from.velocity.map(
    (value, index) =>
      value +
      ((-from.config.stiffness *
        ((from.position[index] ?? 0) - (from.target[index] ?? 0)) -
        from.config.damping * value) /
        from.config.mass) *
        seconds
  );

  return {
    ...from,
    position: from.position.map(
      (value, index) => value + (velocity[index] ?? 0) * seconds
    ),
    velocity,
  };
};

const forgetsVelocity = (
  from: Spring.Spring,
  target: readonly number[]
): Spring.Spring => ({
  ...Spring.retarget(from, target),
  velocity: from.velocity.map(() => 0),
});

const springWithoutSnap = (from: Spring.Spring, elapsed: number) => {
  const next = Spring.step(from, elapsed);

  return Spring.isSettled(next) && !Spring.isSettled(from)
    ? { ...next, position: from.position }
    : next;
};

describe("spring", () => {
  it.prop(
    "a critically damped spring from rest settles within six periods and snaps exactly onto its target",
    { start: criticalStart },
    ({ start: { frequency, spring } }) => {
      expect(settlesAndSnaps(Spring.step, spring, 6000 / frequency)).toBe(true);
    }
  );

  it.prop(
    "a critically damped 1D spring from rest never overshoots",
    { start: criticalStart },
    ({ start: { spring } }) => {
      expect(neverCrossesTarget(spring)).toBe(true);
    }
  );

  it.prop(
    "retargeting keeps position and velocity",
    { from: movingSpring, target: vectorOf(3) },
    ({ from, target }) => {
      expect(keepsMotionAcrossRetarget(Spring.retarget, from, target)).toBe(
        true
      );
    }
  );

  it.prop(
    "one step equals two steps that split it on the substep grid",
    {
      first: integerBetween(0, 6),
      from: anySpring,
      second: integerBetween(0, 6),
    },
    ({ first, from, second }) => {
      expect(splitAgrees(Spring.step, from, first, second)).toBe(true);
    },
    { arbitrary: { runs: 3000 } }
  );

  it.prop(
    "stepping in place into numbers or a Float64Array matches the allocating step",
    { elapsed: between(0, 200), from: movingSpring },
    ({ elapsed, from }) => {
      const expected = Spring.step(from, elapsed);

      const inPlace = Spring.stepInto(from, elapsed, {
        ...from,
        position: [...from.position],
        target: [...from.target],
        velocity: [...from.velocity],
      });

      const typed = Spring.stepInto(from, elapsed, {
        ...from,
        position: Float64Array.from(from.position),
        target: Float64Array.from(from.target),
        velocity: Float64Array.from(from.velocity),
      });

      expect(springsEqual(expected, inPlace)).toBe(true);
      expect([...typed.position]).toStrictEqual(expected.position);
      expect([...typed.velocity]).toStrictEqual(expected.velocity);
    }
  );

  it.prop(
    "a huge frame gap is clamped to the longest step",
    { elapsed: between(Spring.MAX_STEP_MS, 60_000), from: movingSpring },
    ({ elapsed, from }) => {
      expect(
        springsEqual(
          Spring.step(from, elapsed),
          Spring.step(from, Spring.MAX_STEP_MS)
        )
      ).toBe(true);
    }
  );

  it("a fixed step sequence reproduces the golden trajectory", () => {
    let current = Spring.spring({
      config: Spring.springConfig({ damping: 12, mass: 1, stiffness: 170 }),
      position: [0, 100],
      target: [100, 0],
      velocity: [0, -50],
    });

    for (const elapsed of [16, 17, 16, 33, 8, 100, 16]) {
      current = Spring.step(current, elapsed);
    }

    expect(current.position).toStrictEqual([
      110.65426307238269, -11.454357326463569,
    ]);
    expect(current.velocity).toStrictEqual([
      302.25782931943866, -287.5221820176667,
    ]);
    expect(current.remainder).toBeCloseTo(0.72, 12);
  });

  it("names the fix for a spring that cannot move", () => {
    expect(() => Spring.critical(0)).toThrow(/frequency in hertz, above 0/u);
    expect(() =>
      Spring.spring({
        config: Spring.critical(2),
        position: [0, 0],
        target: [1],
      })
    ).toThrow(/same number of components/u);
  });

  describe("planted bugs", () => {
    it.effect("the settle property catches a spring that never snaps", () =>
      falsifies(criticalStart, ({ frequency, spring }) =>
        settlesAndSnaps(springWithoutSnap, spring, 6000 / frequency)
      )
    );

    it.effect("the overshoot property catches an underdamped spring", () =>
      falsifies(criticalStart, ({ spring }) =>
        neverCrossesTarget({
          ...spring,
          config: { ...spring.config, damping: spring.config.damping / 4 },
        })
      )
    );

    it.effect(
      "the retarget property catches a retarget that drops velocity",
      () =>
        falsifies(
          Arbitrary.all([movingSpring, vectorOf(3)]),
          ([from, target]) =>
            keepsMotionAcrossRetarget(forgetsVelocity, from, target)
        )
    );

    it.effect(
      "the frame-rate property catches an integrator that takes whole frames",
      () =>
        falsifies(
          Arbitrary.all([
            movingSpring,
            integerBetween(1, 6),
            integerBetween(1, 6),
          ]),
          ([from, first, second]) =>
            splitAgrees(wholeFrameEuler, from, first, second)
        )
    );
  });
});
